INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1929755, 265867, 47487, '<td valign="top">The idea here is good, but it''s hard to figure out what I''m seeing at first. There are a lot of distractions. Good expression of the theme. 5. Good luck!</td>', 'The idea here is good, but it''s hard to figure out what I''m seeing at first. There are a lot of distractions. Good expression of the theme. 5. Good luck!', '2005-12-07 00:28:01.000000', NULL, 1),
(1929785, 266064, 47487, '<td valign="top">The focus on the nearest piece, which one would expect to be just razor-sharp, is just the tiniest bit off to my eyes. Good idea, though; the picture''s well-composed and I like the colors, very vibrant. Man, I hate it when I draw a Sorry with nobody at Start. :)  6.</td>', 'The focus on the nearest piece, which one would expect to be just razor-sharp, is just the tiniest bit off to my eyes. Good idea, though; the picture''s well-composed and I like the colors, very vibrant. Man, I hate it when I draw a Sorry with nobody at Start. :)  6.', '2005-12-07 00:35:29.000000', NULL, 1),
(1929800, 266171, 47487, '<td valign="top">Very pretty detail on this. I just want to keep looking at it. Pretty light too. All in all an excellent capture.</td>', 'Very pretty detail on this. I just want to keep looking at it. Pretty light too. All in all an excellent capture.', '2005-12-07 00:39:30.000000', NULL, 1),
(1929809, 266133, 47487, '<td valign="top">How you managed to get a goose to look simultaneously miffed and expectant is beyond me but you have my congratulations. Good capture. :)</td>', 'How you managed to get a goose to look simultaneously miffed and expectant is beyond me but you have my congratulations. Good capture. :)', '2005-12-07 00:41:06.000000', NULL, 1),
(1929825, 265011, 45930, '<td valign="top">Don''t think I like the effect you put on this.</td>', 'Don''t think I like the effect you put on this.', '2005-12-07 00:43:51.000000', NULL, 1),
(1929831, 264711, 47487, '<td valign="top">Clever idea. The back of the chair is distracting for a moment, but once I figured out what that was, I didn''t mind it. 6.</td>', 'Clever idea. The back of the chair is distracting for a moment, but once I figured out what that was, I didn''t mind it. 6.', '2005-12-07 00:45:07.000000', NULL, 1),
(1929848, 264539, 45930, '<td valign="top">Bit unrealistic looking (the body), but I like the background.</td>', 'Bit unrealistic looking (the body), but I like the background.', '2005-12-07 00:48:22.000000', NULL, 1),
