(1930024, 265624, 15711, '<td valign="top">Woah!! Bob Dylan revisited. Love the urban scene and the dripping water spout.  The smoking pouring out of his mouth and blowing in the wind is great!! Love this in all its contrast!</td>', 'Woah!! Bob Dylan revisited. Love the urban scene and the dripping water spout.  The smoking pouring out of his mouth and blowing in the wind is great!! Love this in all its contrast!', '2005-12-07 01:37:39.000000', NULL, 1),
(1930028, 265500, 15711, '<td valign="top">ROFL Well executed (but oh, so damp). LOL Thanks for the laugh.  Good composition and contrast.</td>', 'ROFL Well executed (but oh, so damp). LOL Thanks for the laugh.  Good composition and contrast.', '2005-12-07 01:38:51.000000', NULL, 1),
(1930033, 265484, 15711, '<td valign="top">I love the minimalist approach. You have to look at it to figure it out.  I''d maximize to 640 pixels for full impact! 7</td>', 'I love the minimalist approach. You have to look at it to figure it out.  I''d maximize to 640 pixels for full impact! 7', '2005-12-07 01:40:23.000000', NULL, 1),
(1930037, 265039, 15711, '<td valign="top">Very impactful. The velvet smooth of the sky is nice. Great silhouette.</td>', 'Very impactful. The velvet smooth of the sky is nice. Great silhouette.', '2005-12-07 01:40:49.000000', NULL, 1),
(1930054, 265622, 32893, '<td valign="top">Excellent composition!  I like this picture.  Nice focus on the feather; good DOF.</td>', 'Excellent composition!  I like this picture.  Nice focus on the feather; good DOF.', '2005-12-07 01:47:25.000000', NULL, 1),
