(1931988, 266155, 37015, '<td valign="top">I like the concept, however the crack in the egg is too artificial for me and I get hung up on it everytime I look at this photo.  Also, I think the background could be a bit brighter without sacrificing contrast between it and the egg.</td>', 'I like the concept, however the crack in the egg is too artificial for me and I get hung up on it everytime I look at this photo.  Also, I think the background could be a bit brighter without sacrificing contrast between it and the egg.', '2005-12-07 13:49:00.000000', NULL, 1),
(1931991, 265384, 43024, '<td valign="top">good idea, there seems to be an ufo hehe. The dark road at the bottom is uninteresting and gets same space as the sky, I would have definitely croped it. it all seems to be very noisy, perhaps a high ISO. Gotta work more on composition.</td>', 'good idea, there seems to be an ufo hehe. The dark road at the bottom is uninteresting and gets same space as the sky, I would have definitely croped it. it all seems to be very noisy, perhaps a high ISO. Gotta work more on composition.', '2005-12-07 13:49:41.000000', NULL, 1);
