INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1940439, 264539, 3306, '<td valign="top">I hope the baby is right on time! Good use of available props.</td>', 'I hope the baby is right on time! Good use of available props.', '2005-12-10 13:55:18.000000', NULL, 1),
(1940443, 265914, 3306, '<td valign="top">Very good interpretation of the challenge. I like the compostion. One small criticism is that the shiny forhead doesn''t go with the rainy day feel. Otherwise, very well done.</td>', 'Very good interpretation of the challenge. I like the compostion. One small criticism is that the shiny forhead doesn''t go with the rainy day feel. Otherwise, very well done.', '2005-12-10 13:58:03.000000', NULL, 1),
(1940445, 264582, 3306, '<td valign="top">I know the feeling.</td>', 'I know the feeling.', '2005-12-10 13:58:54.000000', NULL, 1),
(1940532, 265803, 41800, '<td valign="top">nice lighting, all around good composition</td>', 'nice lighting, all around good composition', '2005-12-10 15:26:07.000000', NULL, 1),
(1940535, 265622, 41800, '<td valign="top">nice detail in the feather</td>', 'nice detail in the feather', '2005-12-10 15:27:16.000000', NULL, 1),
(1940543, 265547, 47852, '<td valign="top">I like all the lines in this shot, but theres something lacking in the feeling.  Without the title, I wouldn''t have known how this fit the challenge theme.</td>', 'I like all the lines in this shot, but theres something lacking in the feeling.  Without the title, I wouldn''t have known how this fit the challenge theme.', '2005-12-10 15:31:17.000000', NULL, 1),
(1940547, 265818, 41800, '<td valign="top">nice shot.</td>', 'nice shot.', '2005-12-10 15:32:12.000000', NULL, 1),
(1940554, 265818, 47852, '<td valign="top">Eww!  But what a creative concept for this challenge!  It seems just a tad out of focus, but otherwise a great shot!</td>', 'Eww!  But what a creative concept for this challenge!  It seems just a tad out of focus, but otherwise a great shot!', '2005-12-10 15:35:13.000000', NULL, 1),
(1940557, 265902, 47852, '<td valign="top">I think this shot might have been better if the plant seemed more dead than the surroundings.</td>', 'I think this shot might have been better if the plant seemed more dead than the surroundings.', '2005-12-10 15:36:31.000000', NULL, 1),
(1940562, 264582, 47852, '<td valign="top">Ahh! Don''t you hate that!  I like the feeling that this image gives.  The fresh snow cover makes it a beautiful shot!  As I look more closely, there are 2 things that bother me though... the trash cans down the street are all still snow covered, meaning that none of them have been emptied, and there is a bit of clutter from the front of the next house to the right of the photo.  Overall though, one of my favorites so far!  Nicely done!</td>', 'Ahh! Don''t you hate that!  I like the feeling that this image gives.  The fresh snow cover makes it a beautiful shot!  As I look more closely, there are 2 things that bother me though... the trash cans down the street are all still snow covered, meaning that none of them have been emptied, and there is a bit of clutter from the front of the next house to the right of the photo.  Overall though, one of my favorites so far!  Nicely done!', '2005-12-10 15:39:26.000000', NULL, 1),
(1940566, 265971, 47852, '<td valign="top">The yellow border seems a bit out of place on this one, but I do like the photo.</td>', 'The yellow border seems a bit out of place on this one, but I do like the photo.', '2005-12-10 15:41:20.000000', NULL, 1),
(1940574, 266103, 47852, '<td valign="top">Too dark.  Perhaps a candle off to the side could have provided a little light for the burnt out match?</td>', 'Too dark.  Perhaps a candle off to the side could have provided a little light for the burnt out match?', '2005-12-10 15:47:13.000000', NULL, 1),
(1940587, 265622, 47852, '<td valign="top">Had to take a 2nd look to figure this one out since I didn''t see the cat right away.  Cute idea... perhaps a little more of the cat would help it stand out?  Nicely done though!</td>', 'Had to take a 2nd look to figure this one out since I didn''t see the cat right away.  Cute idea... perhaps a little more of the cat would help it stand out?  Nicely done though!', '2005-12-10 15:53:46.000000', NULL, 1),
(1940621, 264927, 48245, '<td valign="top">okay... this was funny</td>', 'okay... this was funny', '2005-12-10 16:18:56.000000', NULL, 1),
(1940713, 266171, 70, '<td valign="top">Even with your title, I don''t feel like this has a very strong connection to the challenge topic. The photo itself is nice - nice lighting and good detail.</td>', 'Even with your title, I don''t feel like this has a very strong connection to the challenge topic. The photo itself is nice - nice lighting and good detail.', '2005-12-10 17:29:55.000000', NULL, 1),
(1940721, 265031, 70, '<td valign="top">Beautiful scene. Not an especially strong connection to the challenge without the title. Possibly a bit oversharpened?</td>', 'Beautiful scene. Not an especially strong connection to the challenge without the title. Possibly a bit oversharpened?', '2005-12-10 17:33:42.000000', NULL, 1),
(1940723, 265724, 70, '<td valign="top">Oh, too cute! Seems like there may be a bit of a yellow cast to the photo.</td>', 'Oh, too cute! Seems like there may be a bit of a yellow cast to the photo.', '2005-12-10 17:34:58.000000', NULL, 1),
(1940727, 264003, 70, '<td valign="top">Nice set up. I like the lighting except for maybe the hot spot in the lower right corner. The photo really needs the title to make any sort of sense out of how it fits the challenge.</td>', 'Nice set up. I like the lighting except for maybe the hot spot in the lower right corner. The photo really needs the title to make any sort of sense out of how it fits the challenge.', '2005-12-10 17:40:07.000000', NULL, 1),
(1940733, 263937, 70, '<td valign="top">A rainy day indeed. What does this have to do with too late? Even aside from the challenge, there doesn''t seem to be a point of interest in this photo. It''s also a bit out of focus and somewhat flat.</td>', 'A rainy day indeed. What does this have to do with too late? Even aside from the challenge, there doesn''t seem to be a point of interest in this photo. It''s also a bit out of focus and somewhat flat.', '2005-12-10 17:45:28.000000', NULL, 1),
(1940738, 265816, 70, '<td valign="top">I''m not quite sure what that is in the background (candle? vase?) but it''s awfully distracting.  The concept is good and the colors of the flower are quite pretty. Perhaps more flower?</td>', 'I''m not quite sure what that is in the background (candle? vase?) but it''s awfully distracting.  The concept is good and the colors of the flower are quite pretty. Perhaps more flower?', '2005-12-10 17:49:58.000000', NULL, 1),
(1940741, 265523, 70, '<td valign="top">I love this photo. Beautiful lighting and toning. Fairly weak connection to the challenge, though.</td>', 'I love this photo. Beautiful lighting and toning. Fairly weak connection to the challenge, though.', '2005-12-10 17:51:17.000000', NULL, 1),
(1940745, 266141, 48583, '<td valign="top">this one is my fav in this contest. very cute and the colors are awesome with the snow as the back ground. good job.</td>', 'this one is my fav in this contest. very cute and the colors are awesome with the snow as the back ground. good job.', '2005-12-10 17:52:17.000000', NULL, 1),
