INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1945143, 265558, 48717, '<td valign="top">Nice pic, but I don''t get it?</td>', 'Nice pic, but I don''t get it?', '2005-12-12 17:03:08.000000', NULL, 1),
(1945144, 264003, 48717, '<td valign="top">Always sad :-( <br/>Nice pic.</td>', 'Always sad :-( Nice pic.', '2005-12-12 17:03:54.000000', NULL, 1),
(1945146, 266171, 48717, '<td valign="top">Great pic, nice detail.</td>', 'Great pic, nice detail.', '2005-12-12 17:04:52.000000', NULL, 1),
(1945186, 265121, 6999, '<td valign="top">There''s an impression of dirt and loneliness to this that quite appeals - certainly different around here. The bluw lights are interesting, and different, but I don''t find it a very engaging photograph - I don''t mean ''pretty'' or anything like that - simply I''m not pulled in to whatever you''re presenting to me - perhaps because I don''t quite see what that is. The snowbound world? But then your title and the shot move the interest away from that. Different in a good way, but it feels, perhaps, different for the sake of it.</td>', 'There''s an impression of dirt and loneliness to this that quite appeals - certainly different around here. The bluw lights are interesting, and different, but I don''t find it a very engaging photograph - I don''t mean ''pretty'' or anything like that - simply I''m not pulled in to whatever you''re presenting to me - perhaps because I don''t quite see what that is. The snowbound world? But then your title and the shot move the interest away from that. Different in a good way, but it feels, perhaps, different for the sake of it.', '2005-12-12 17:26:46.000000', NULL, 1),
(1945188, 265500, 6999, '<td valign="top">I really hope this wasn''t set up: but I have remarkably little optimism for that. Has a good sense of the imstant shot for the situation - nice and shiny would have defeated the joke I guess. Funny also - but the joke doesn''t last everso: it''s a one-liner in that sense, requiring a swift move on to the next gag. Can''t see you scoring well without finding a bit more depth to things.</td>', 'I really hope this wasn''t set up: but I have remarkably little optimism for that. Has a good sense of the imstant shot for the situation - nice and shiny would have defeated the joke I guess. Funny also - but the joke doesn''t last everso: it''s a one-liner in that sense, requiring a swift move on to the next gag. Can''t see you scoring well without finding a bit more depth to things.', '2005-12-12 17:29:28.000000', NULL, 1),
(1945205, 264817, 6999, '<td valign="top">Good sense of the onset of winter, particularly aginst the idea of the playground. You''ve done well also with your exposure, to keep the sky under control and some interest on the foreground. The white line at the top of frame is kind of clumsy. I might have tried to shoot from even lower, to emphasise the silhouettes against the sky without losing so much against the tree-line: whilst the ordinariness of this presentation works in your favour, I think a more imposing composition would have given more effect - and the difference simply kneeling down can produce can be amazing. Some kind of fill-light process, which exists in PSP10 and in RSE might have helped bring back some foreground detail, to enhance the feeling of desertion, without blowing out the sky.</td>', 'Good sense of the onset of winter, particularly aginst the idea of the playground. You''ve done well also with your exposure, to keep the sky under control and some interest on the foreground. The white line at the top of frame is kind of clumsy. I might have tried to shoot from even lower, to emphasise the silhouettes against the sky without losing so much against the tree-line: whilst the ordinariness of this presentation works in your favour, I think a more imposing composition would have given more effect - and the difference simply kneeling down can produce can be amazing. Some kind of fill-light process, which exists in PSP10 and in RSE might have helped bring back some foreground detail, to enhance the feeling of desertion, without blowing out the sky.', '2005-12-12 17:34:11.000000', NULL, 1),
(1945212, 266056, 6999, '<td valign="top">Quite clever. Colouring is good, though there seems to be some lack of steadiness to the shot - lack of detail showing in the wires. The composition is fun too - though perhaps keeping slightly more of the wires in shot might have helped overall, this is nevertheless quite effective - that framing of the two sides of the image. Given the absence of any human engagement, this is not at all bad thinking.</td>', 'Quite clever. Colouring is good, though there seems to be some lack of steadiness to the shot - lack of detail showing in the wires. The composition is fun too - though perhaps keeping slightly more of the wires in shot might have helped overall, this is nevertheless quite effective - that framing of the two sides of the image. Given the absence of any human engagement, this is not at all bad thinking.', '2005-12-12 17:37:11.000000', NULL, 1),
(1945225, 266155, 48717, '<td valign="top">Wonderful pic, but I am not sure I understand what is going on.</td>', 'Wonderful pic, but I am not sure I understand what is going on.', '2005-12-12 17:40:50.000000', NULL, 1),
(1945226, 265902, 6999, '<td valign="top">This has a strong sense, and not just from the title, of a child''s shot. It has a bland kind of naivete about it - not to mention the absolutely contradictory near-greying out of the greens mentioned in the title. Compositionally it just a bit too weak for me to think it was deliberately done - the neat angles of the lawn are too far out of frame, the light is poor on the  water so that it takes a few moments to register it. As to meeting the challenge -</td>', 'This has a strong sense, and not just from the title, of a child''s shot. It has a bland kind of naivete about it - not to mention the absolutely contradictory near-greying out of the greens mentioned in the title. Compositionally it just a bit too weak for me to think it was deliberately done - the neat angles of the lawn are too far out of frame, the light is poor on the  water so that it takes a few moments to register it. As to meeting the challenge -', '2005-12-12 17:41:19.000000', NULL, 1),
(1945238, 265950, 6999, '<td valign="top">Don''t understand. The lens zoom, or the motion, whatever, is effective as ever - although quite a tired effect to my eyes, iyt still remains a great sense of motion. The point, however, escapes me. My thought was that it had implications of running someone over, but the blocks behind the figures remove that sense. If the implication was more sinister, or even subtle, then i think there is too much going on here for that to come through. Outside of challenge things, there isn''t enough sense of process for me to like it at all - I think at least some definition to that central face would be useful to the viewer.</td>', 'Don''t understand. The lens zoom, or the motion, whatever, is effective as ever - although quite a tired effect to my eyes, iyt still remains a great sense of motion. The point, however, escapes me. My thought was that it had implications of running someone over, but the blocks behind the figures remove that sense. If the implication was more sinister, or even subtle, then i think there is too much going on here for that to come through. Outside of challenge things, there isn''t enough sense of process for me to like it at all - I think at least some definition to that central face would be useful to the viewer.', '2005-12-12 17:45:02.000000', NULL, 1),
(1945255, 266083, 6999, '<td valign="top">Strong shot - though I lament the lack of a touch more environment - a sense of what the hell''s going on would, I think, help; where you have simply a portrait - a well done, well toned, great contrast portrait however. I can see the rain, and a sense of steaminess/fogginess behind, but only s sense. Black and white works well, especially in the cpature of that reflected light around his face, but the half-silhouette, and  his weak position in frame detract somewhat from great-shot potential. It looks like full frame, so even some juducious cropping might have helped a touch - if it''s going to b e a portrait, really force the attention to the subject, huh? Pretty good work, though, for all those points.</td>', 'Strong shot - though I lament the lack of a touch more environment - a sense of what the hell''s going on would, I think, help; where you have simply a portrait - a well done, well toned, great contrast portrait however. I can see the rain, and a sense of steaminess/fogginess behind, but only s sense. Black and white works well, especially in the cpature of that reflected light around his face, but the half-silhouette, and  his weak position in frame detract somewhat from great-shot potential. It looks like full frame, so even some juducious cropping might have helped a touch - if it''s going to b e a portrait, really force the attention to the subject, huh? Pretty good work, though, for all those points.', '2005-12-12 17:50:04.000000', NULL, 1),
(1945268, 265726, 6999, '<td valign="top">The moment is quite interesting - the stillness of the number 13 against her opponents works well. There are a number of things one would like to see to improve n the dynamic and power of the moment though: getting the instant of shutter release right is one thing, but there are others. The angle of shooting is strange - if you could get lower you''d get more impact, and certainly more emphasis of the relative height of the girls and the effort involved in the jumps. The line of the crash mats would be less intrusive also, and you''d perhaps have the added dramam of shooting into the lights, with the great geometric effects to be gained there. Some contrast work in post-processing would also be nice - either to make those colours pop a touch more, or to remove them, and use black and white to get into the physicality of the sport.</td>', 'The moment is quite interesting - the stillness of the number 13 against her opponents works well. There are a number of things one would like to see to improve n the dynamic and power of the moment though: getting the instant of shutter release right is one thing, but there are others. The angle of shooting is strange - if you could get lower you''d get more impact, and certainly more emphasis of the relative height of the girls and the effort involved in the jumps. The line of the crash mats would be less intrusive also, and you''d perhaps have the added dramam of shooting into the lights, with the great geometric effects to be gained there. Some contrast work in post-processing would also be nice - either to make those colours pop a touch more, or to remove them, and use black and white to get into the physicality of the sport.', '2005-12-12 18:00:10.000000', NULL, 1),
(1945292, 266046, 6999, '<td valign="top">Perhaps a slightly obvious way of meeting the challenge - but it makes it over those whose aproach seems entirely arbitrary. There''s some very strong elements to this photography, but it''s just a touch let dow n in a couple of areas for me. The central interest of the image seems squeezed to me - some of which will be to do with the point of view - the standing viewpoint always feels quite ordinary, unless your subject is enormously momentous in its own right. A lower POV, framing those gravelstones against the sky and the distant hills would have added enormous impact to the stones and their cage. Alternatively, a wider-angle shot, with the stones more to the foreground, so that you could emphasise the separation between the two worlds, would perhaps have been effective. You could also have sued more contrast here I think - the colours are very washed out, and yet you haven''t chosen a black-and-white approach - deeper shadows would make this the more mournful and impressive too. <br/> <br/>It has real potential, though, this: just needs some work to bring it out I think - one can see the detail in thsoe hills.</td>', 'Perhaps a slightly obvious way of meeting the challenge - but it makes it over those whose aproach seems entirely arbitrary. There''s some very strong elements to this photography, but it''s just a touch let dow n in a couple of areas for me. The central interest of the image seems squeezed to me - some of which will be to do with the point of view - the standing viewpoint always feels quite ordinary, unless your subject is enormously momentous in its own right. A lower POV, framing those gravelstones against the sky and the distant hills would have added enormous impact to the stones and their cage. Alternatively, a wider-angle shot, with the stones more to the foreground, so that you could emphasise the separation between the two worlds, would perhaps have been effective. You could also have sued more contrast here I think - the colours are very washed out, and yet you haven''t chosen a black-and-white approach - deeper shadows would make this the more mournful and impressive too.  It has real potential, though, this: just needs some work to bring it out I think - one can see the detail in thsoe hills.', '2005-12-12 18:17:30.000000', NULL, 1),
(1945317, 265546, 6999, '<td valign="top">Very blocky composition, the situation itself is likewise blatant - beyond the meter and the penalty and the chewing gum (and that needed your title to explain, and still isn''t something familiar), what else is there? There''s a very poor resolution feel to the image overall - though whether that''s processing or camera I can''t say, but it doesn''t help you. Joke shots are of course a matter of taste, but also i think to be genuinely effective there has to be more to the image than simply the joke - you want people to come back to the image, then the joke either has to be exceptionally profound or there has to more depth to the photograph. Mind you, enough joke set-ups have won recently that I can forgive the attempt ...</td>', 'Very blocky composition, the situation itself is likewise blatant - beyond the meter and the penalty and the chewing gum (and that needed your title to explain, and still isn''t something familiar), what else is there? There''s a very poor resolution feel to the image overall - though whether that''s processing or camera I can''t say, but it doesn''t help you. Joke shots are of course a matter of taste, but also i think to be genuinely effective there has to be more to the image than simply the joke - you want people to come back to the image, then the joke either has to be exceptionally profound or there has to more depth to the photograph. Mind you, enough joke set-ups have won recently that I can forgive the attempt ...', '2005-12-12 18:24:01.000000', NULL, 1),
(1945334, 265811, 6999, '<td valign="top">I couldn''t say why, but I think this meets the old challenge there. Composition, however, lets it down for me - the sun betwen the pylons is nice, but the framing of the pylons in your image is clumsy  - half-centred, but not cnetred, half-privileged, but not privileged. I think you''ve falled between giving them more space, and composing tightly to them, and the result feels half-hearted. Groups of subjects are always tricky like that - my feeling is that you either need to treat them as one subject, in which case give them more surrounding and compose for the one subject, or treat them as a pair and try to centre the as a pair, using what symmetry they give you as the strength of the composition.</td>', 'I couldn''t say why, but I think this meets the old challenge there. Composition, however, lets it down for me - the sun betwen the pylons is nice, but the framing of the pylons in your image is clumsy  - half-centred, but not cnetred, half-privileged, but not privileged. I think you''ve falled between giving them more space, and composing tightly to them, and the result feels half-hearted. Groups of subjects are always tricky like that - my feeling is that you either need to treat them as one subject, in which case give them more surrounding and compose for the one subject, or treat them as a pair and try to centre the as a pair, using what symmetry they give you as the strength of the composition.', '2005-12-12 18:28:43.000000', NULL, 1),
(1945366, 265683, 48717, '<td valign="top">Beautiful color!  Really nice pic.</td>', 'Beautiful color!  Really nice pic.', '2005-12-12 18:38:29.000000', NULL, 1),
(1945379, 265814, 6999, '<td valign="top">Like this - strong stuff. Especially like the isloation of the scene within frame, and a certain sense of mystery to it. One could quibble about the specifics of meeting the challenge, but it has that vibe to it so it''s fine by me - wouldn''t be surprise dif you get knocked slightly for it though: though not as much as for the unusualness of it :-) Good work, the most interesting shot so far.</td>', 'Like this - strong stuff. Especially like the isloation of the scene within frame, and a certain sense of mystery to it. One could quibble about the specifics of meeting the challenge, but it has that vibe to it so it''s fine by me - wouldn''t be surprise dif you get knocked slightly for it though: though not as much as for the unusualness of it :-) Good work, the most interesting shot so far.', '2005-12-12 18:44:24.000000', NULL, 1),
(1945391, 264872, 6999, '<td valign="top">Could use some processing, to start with - would be nice to take the ground completely black if you''re working with silhouettes, really - rather than this almost black here. Good to get down for the low POV, always effective. Sharpening needs to be more under control - very noticeable halos around the edges of the plough. The sunset is kind of effective - though also the kind of easy thing that annoys sometimes, but your skyline is a bit random and busy, and your framing of the plough maybe too tight in this shot - give it some room to breath - especially in this ''too late'' challenge, it might benefit from seeming more isolated in its environment.</td>', 'Could use some processing, to start with - would be nice to take the ground completely black if you''re working with silhouettes, really - rather than this almost black here. Good to get down for the low POV, always effective. Sharpening needs to be more under control - very noticeable halos around the edges of the plough. The sunset is kind of effective - though also the kind of easy thing that annoys sometimes, but your skyline is a bit random and busy, and your framing of the plough maybe too tight in this shot - give it some room to breath - especially in this ''too late'' challenge, it might benefit from seeming more isolated in its environment.', '2005-12-12 18:48:51.000000', NULL, 1),
(1945405, 265136, 6999, '<td valign="top">Poor light - very flat, very uninteresting. there''s a certain weirdness of shapes and angles here that might have been brought out so much more effectively with a more directional sot light.</td>', 'Poor light - very flat, very uninteresting. there''s a certain weirdness of shapes and angles here that might have been brought out so much more effectively with a more directional sot light.', '2005-12-12 18:53:32.000000', NULL, 1),
(1945421, 266002, 6999, '<td valign="top">The first thought is that its impossible to know whether the train is coming or going. The second is that if this isn''t a set-up, which I suspect it isn''t somehow, then I think you perhaps need to go into b/w territory: it at least gives an edge of reportage that makes the ordinary more interesting - and this is fairly ordinary, really; and perhaps use processing to pull out the sense of those out-stretched arms, whicha are the real point of this scene - they''re what communicates your message here. Keeping the far side of the tracks properly exposed is useless if it means relegating her pose into the shadows. If it was set-up, then you needed to capture some motion in the train, at the very least, as well as putting more into the compositional elements.</td>', 'The first thought is that its impossible to know whether the train is coming or going. The second is that if this isn''t a set-up, which I suspect it isn''t somehow, then I think you perhaps need to go into b/w territory: it at least gives an edge of reportage that makes the ordinary more interesting - and this is fairly ordinary, really; and perhaps use processing to pull out the sense of those out-stretched arms, whicha are the real point of this scene - they''re what communicates your message here. Keeping the far side of the tracks properly exposed is useless if it means relegating her pose into the shadows. If it was set-up, then you needed to capture some motion in the train, at the very least, as well as putting more into the compositional elements.', '2005-12-12 18:59:10.000000', NULL, 1),
(1945438, 265286, 6999, '<td valign="top">Whilst smaller sizes in vertical images perhaps help for those on low resolutions, this realy comes across as very very small on a high-res screen. I suspect there''s a kertesz-like interplay of shapes here - he had some fine images of Washington Square in the snow, and of the Tuileries playing on similar themes.</td>', 'Whilst smaller sizes in vertical images perhaps help for those on low resolutions, this realy comes across as very very small on a high-res screen. I suspect there''s a kertesz-like interplay of shapes here - he had some fine images of Washington Square in the snow, and of the Tuileries playing on similar themes.', '2005-12-12 19:05:05.000000', NULL, 1),
(1945492, 265039, 6999, '<td valign="top">Is this a deliberate tug at the heart-strings I''m feeling? I think your composition moight have been stronger - the cross is toofar into frame for real effect. Nice techncial work, in a scene I really don''t like at all, personally.</td>', 'Is this a deliberate tug at the heart-strings I''m feeling? I think your composition moight have been stronger - the cross is toofar into frame for real effect. Nice techncial work, in a scene I really don''t like at all, personally.', '2005-12-12 19:30:51.000000', NULL, 1),
(1945587, 265700, 6999, '<td valign="top">Whilst there''s an awful lot to like about this - and like it i do, certainly, one of the best I''ve seen in this challenge - I can''t help feeling that the framing and the crop are a touch arbitrary. Is so much gained from the inclusion of the boardwalk that you mightn''t have placed the fishermen and the rail more orthodoxly within frame? You''d have saved some of teh distortion of the angle of the lamppost, and wouldn''t have lost the boards completely, and i think the shot would have been more about the fishermen than this slightly strange composition which appears to be about the boards as much as the people - it almost feels wilfully an odd composition, and I think the image would be strong enough not to need that.</td>', 'Whilst there''s an awful lot to like about this - and like it i do, certainly, one of the best I''ve seen in this challenge - I can''t help feeling that the framing and the crop are a touch arbitrary. Is so much gained from the inclusion of the boardwalk that you mightn''t have placed the fishermen and the rail more orthodoxly within frame? You''d have saved some of teh distortion of the angle of the lamppost, and wouldn''t have lost the boards completely, and i think the shot would have been more about the fishermen than this slightly strange composition which appears to be about the boards as much as the people - it almost feels wilfully an odd composition, and I think the image would be strong enough not to need that.', '2005-12-12 20:20:28.000000', NULL, 1),
(1945624, 265011, 35804, '<td valign="top">Fabulous electric/neon lighting an color! Cool cars and stainless steel diners...hardly gets any better than this...very nice.</td>', 'Fabulous electric/neon lighting an color! Cool cars and stainless steel diners...hardly gets any better than this...very nice.', '2005-12-12 20:30:20.000000', NULL, 1),
(1945628, 264597, 35804, '<td valign="top">...bad kitty!  : }</td>', '...bad kitty!  : }', '2005-12-12 20:31:08.000000', NULL, 1),
(1945637, 266141, 35804, '<td valign="top">Love the bathing cap! Do they still makes those crazy ones with the flowers on them? I used to have one when I was that age...it was the collest thing...cute picture and I hope you made it worth her while once ya got in!  : }</td>', 'Love the bathing cap! Do they still makes those crazy ones with the flowers on them? I used to have one when I was that age...it was the collest thing...cute picture and I hope you made it worth her while once ya got in!  : }', '2005-12-12 20:34:14.000000', NULL, 1),
(1945648, 266097, 35804, '<td valign="top">...fantastic idea!...and funny too...what more could anyone want! Very nicely done.</td>', '...fantastic idea!...and funny too...what more could anyone want! Very nicely done.', '2005-12-12 20:39:00.000000', NULL, 1),
(1945862, 264149, 43298, '<td valign="top">Ketchup......?</td>', 'Ketchup......?', '2005-12-12 22:12:04.000000', NULL, 1),
